package com.fakelegacy.order.service;

import java.math.BigDecimal;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import com.fakelegacy.order.client.CustomerClient;
import com.fakelegacy.order.client.CustomerSnapshot;
import com.fakelegacy.order.client.RemoteResult;
import com.fakelegacy.order.domain.Order;
import com.fakelegacy.order.web.ApiRequests.PayRequest;

@Service
public class PaymentService {

    private static final BigDecimal POINT_VALUE = new BigDecimal("0.05");

    @Autowired
    private CustomerClient customerClient;

    /** Validates the payment request and performs the side effects on customer-service (points, credit). */
    public PaymentOutcome process(Order order, CustomerSnapshot customer, PayRequest req) {
        String method = req.method() == null ? "" : req.method().trim().toUpperCase();
        int points = req.loyaltyPoints() == null ? 0 : req.loyaltyPoints();

        if (points < 0) {
            return PaymentOutcome.failure("loyaltyPoints cannot be negative");
        }
        if (points > 0) {
            if (points % 100 != 0) {
                return PaymentOutcome.failure("loyalty points must be a multiple of 100");
            }
            if (customer.isB2b()) {
                return PaymentOutcome.failure("business customers cannot pay with loyalty points");
            }
        }
        BigDecimal pointsValue = POINT_VALUE.multiply(BigDecimal.valueOf(points));
        BigDecimal due = order.getTotalTtc().subtract(pointsValue);

        switch (method) {
            case "CARD":
                String card = req.cardNumber();
                if (card == null || !card.matches("\\d{12,19}")) {
                    return PaymentOutcome.failure("a valid cardNumber (12 to 19 digits) is required");
                }
                if (card.endsWith("0000")) {
                    return PaymentOutcome.failure("card declined");
                }
                break;
            case "B2B_CREDIT":
                if (!customer.isB2b()) {
                    return PaymentOutcome.failure("B2B_CREDIT is reserved to business customers");
                }
                break;
            case "CHEQUE":
                return PaymentOutcome.failure("cheques are no longer accepted");
            default:
                return PaymentOutcome.failure("unknown payment method: " + req.method());
        }

        if (points > 0) {
            RemoteResult r = customerClient.redeem(order.getCustomerId(), points, order.getGoodsTtc(), order.getReference());
            if (!r.isOk()) {
                return PaymentOutcome.failure(r.getMessage());
            }
        }
        if ("B2B_CREDIT".equals(method)) {
            RemoteResult r = customerClient.consumeCredit(order.getCustomerId(), due);
            if (!r.isOk()) {
                if (points > 0) {
                    customerClient.redeem(order.getCustomerId(), -points, null, order.getReference());
                }
                return PaymentOutcome.failure(r.getMessage());
            }
        }
        return PaymentOutcome.success(method, points, due);
    }

    /** Undoes what process() did, used when stock confirmation fails afterwards. */
    public void rollback(Order order, PaymentOutcome outcome) {
        if (outcome.getRedeemedPoints() > 0) {
            customerClient.redeem(order.getCustomerId(), -outcome.getRedeemedPoints(), null, order.getReference());
        }
        if ("B2B_CREDIT".equals(outcome.getMethod())) {
            customerClient.consumeCredit(order.getCustomerId(), outcome.getAmountDue().negate());
        }
    }
}
